    "序列5守护者在放弃攻击时进入防御极强的守护状态，对各类攻击具有强大防护；主动攻击会降低防御，不能一边维持完整守护一边伤害敌人。守护者不被幻术迷惑，并能替附近同伴承担伤害；这不是读心、自动识别邪恶或任意远程替伤。本段3灵性、3米范围、半数分担与全部判定均以当前说明为准。晨曦、晨曦铠甲、晨曦武器与光之风暴继承序列6原能力ID和掌握，不另送光剑、光甲或永久无伤。序列4猎魔者的邪恶与污染辨识、隐藏意图识别、怪物弱点及材料知识、针对性药膏和神话形态不提前下放。原成年导师奥斯温·布莱克特、原成年院工维拉（Vera Edridge）、本人新同意、三处不同的原软垫摆锤、唯一原纸靶GD5-TARGET-1、实际2米到场与返程、成品渠道、成熟周数、费用和数值均以当前说明为准。6健康仅是本次低强度安全探测的基线，不代表真实武器的固定伤害。准备仅约定本次安排，维拉尚在相邻等待点；实施时才沿原2米标线走入现场，结束时实际沿原路走回。失败仍保留实际伤害，退出不治疗，也不补造原器具。旧战士、格斗家、武器大师与黎明骑士历史、借棍物权和已解决敌人的后果均保持。"
