    "铁血骑士可操控多种火焰，令自身火焰化、钢铁化；原女性身体在晋升后变为男性。资深叶戈尔能汇聚建立真实联系的成员力量，并把负担分给实际成员、借联系交流及借用真实成员视野。范围、连接数、分摊比例和成本均以当前说明为准；仅有当前实际到场与同意的原成员参与。没有免疫、凭空军队、全军自动强化、传送或提前获得战争主教3。"
